(()=>{'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const STORE='ilyas-studio-projects-v1';let projects=[],project=null,selected=null,tool='select',showGrid=true,zoom=1,pan={x:0,y:0},drag=null,history=[],future=[],running=false,game=null,keys={},toastTimer;
const defs={Player:{icon:'◆',color:'#ff4657',w:30,h:38,behaviors:['platformer','gravity','collision']},Enemy:{icon:'☠',color:'#ff765b',w:30,h:30,behaviors:['patrol','collision','damagePlayer']},Platform:{icon:'▬',color:'#737f96',w:150,h:18,behaviors:['collision']},Wall:{icon:'▮',color:'#6a7184',w:25,h:130,behaviors:['collision']},Ground:{icon:'▰',color:'#555f72',w:500,h:30,behaviors:['collision']},Coin:{icon:'✦',color:'#ffc65d',w:22,h:22,behaviors:['collectCoin']},Goal:{icon:'⚑',color:'#56d6a0',w:35,h:48,behaviors:['win']},Checkpoint:{icon:'⚑',color:'#6cb6ff',w:28,h:36,behaviors:['checkpoint']},'Moving platform':{icon:'↔',color:'#8b78d5',w:120,h:16,behaviors:['collision','moveBetween']},Spike:{icon:'▲',color:'#ff586b',w:38,h:28,behaviors:['damagePlayer']},Collectible:{icon:'✧',color:'#67e5e0',w:22,h:22,behaviors:['collectCoin']},Background:{icon:'▧',color:'#292d3a',w:960,h:540,behaviors:[]},Text:{icon:'T',color:'#ffffff',w:160,h:34,behaviors:['displayText']},Rectangle:{icon:'▰',color:'#ff4657',w:100,h:70,behaviors:[]},Circle:{icon:'●',color:'#ff4657',w:60,h:60,behaviors:[]},'Custom sprite':{icon:'▧',color:'#a0a0b0',w:60,h:60,behaviors:[]}};
const templates=[['Platformer','Run, jump, and collect coins.','▰'],['Top-down adventure','Explore a little world.','✥'],['Endless runner','Dodge hazards and keep moving.','➜'],['Space shooter','A small arena for space action.','✦'],['AI Combat Arena','Fight smart enemies with programmable visual blocks.','⚔'],['Empty project','A clean canvas for your idea.','＋']];
const playerCombatCode="# @export speed: float = 210\n# @export attack_damage: int = 25\n# @export attack_range: float = 92\n# @export attack_cooldown: float = 0.35\nclass PlayerCombatController:\n    def ready(self):\n        self.speed = ilyas.export(\"speed\", 210)\n        self.attack_damage = ilyas.export(\"attack_damage\", 25)\n        self.attack_range = ilyas.export(\"attack_range\", 92)\n        self.attack_cooldown = ilyas.export(\"attack_cooldown\", 0.35)\n        self.attack_timer = 0\n        ilyas.log(\"Player combat ready — move with WASD/arrows, attack with E\")\n    def update(self, delta):\n        player = ilyas.get_self()\n        if player is None or player.health <= 0: return\n        dx = int(ilyas.get_input(\"right\")) - int(ilyas.get_input(\"left\"))\n        dy = int(ilyas.get_input(\"down\")) - int(ilyas.get_input(\"up\"))\n        length = max((dx*dx + dy*dy) ** 0.5, 1)\n        width, height = ilyas.get_viewport_size()\n        player.x = max(player.width/2, min(width-player.width/2, player.x + dx/length*self.speed*delta))\n        player.y = max(player.height/2, min(height-player.height/2, player.y + dy/length*self.speed*delta))\n        self.attack_timer = max(0, self.attack_timer - delta)\n        if ilyas.get_input(\"dash_pressed\") and self.attack_timer <= 0:\n            candidates = [enemy for enemy in ilyas.get_nodes_by_type(\"Enemy\") if enemy.health > 0 and player.distance_to(enemy) <= self.attack_range]\n            if candidates:\n                enemy = min(candidates, key=lambda node: player.distance_to(node))\n                enemy.health = max(0, enemy.health - self.attack_damage)\n                enemy.color = \"#ff334f\"\n                ilyas.log(\"Hit \" + enemy.name + \" — HP: \" + str(int(enemy.health)))\n                if enemy.health <= 0:\n                    ilyas.destroy(enemy)\n                    ilyas.add_score(10)\n                    ilyas.log(enemy.name + \" defeated! +10 score\")\n            self.attack_timer = self.attack_cooldown\n";
const enemyAIProCode="# @export speed: float = 105\n# @export detection_range: float = 280\n# @export attack_range: float = 42\n# @export attack_damage: int = 10\n# @export attack_cooldown: float = 0.9\n# @export max_health: int = 60\n# @export patrol_range: float = 90\n# @export patrol_speed: float = 1.2\nclass EnemyAIPro:\n    def ready(self):\n        self.speed = ilyas.export(\"speed\", 105)\n        self.detection_range = ilyas.export(\"detection_range\", 280)\n        self.attack_range = ilyas.export(\"attack_range\", 42)\n        self.attack_damage = ilyas.export(\"attack_damage\", 10)\n        self.attack_cooldown = ilyas.export(\"attack_cooldown\", 0.9)\n        self.max_health = ilyas.export(\"max_health\", 60)\n        self.patrol_range = ilyas.export(\"patrol_range\", 90)\n        self.patrol_speed = ilyas.export(\"patrol_speed\", 1.2)\n        self.attack_timer = 0\n        self.origin_x = None\n        self.origin_y = None\n        self.state = \"patrol\"\n        enemy = ilyas.get_self()\n        if enemy is not None:\n            self.origin_x, self.origin_y = enemy.x, enemy.y\n            enemy.health = self.max_health\n            enemy.color = \"#ff745e\"\n            ilyas.log(enemy.name + \" AI ready\")\n    def update(self, delta):\n        enemy = ilyas.get_self()\n        player = ilyas.get_player()\n        if enemy is None or player is None or player.health <= 0: return\n        if self.origin_x is None:\n            self.origin_x, self.origin_y = enemy.x, enemy.y\n        self.attack_timer = max(0, self.attack_timer - delta)\n        distance = enemy.distance_to(player)\n        if distance <= self.attack_range:\n            self.state = \"attack\"\n            enemy.color = \"#ff334f\"\n            if self.attack_timer <= 0:\n                player.health = max(0, player.health - self.attack_damage)\n                self.attack_timer = self.attack_cooldown\n                ilyas.log(enemy.name + \" attacked! Player HP: \" + str(int(player.health)))\n        elif distance <= self.detection_range:\n            self.state = \"chase\"\n            enemy.color = \"#ffb14d\"\n            enemy.move_toward(player, self.speed * delta)\n        else:\n            self.state = \"patrol\"\n            enemy.color = \"#ff745e\"\n            enemy.x = self.origin_x + math.sin(ilyas.get_time() * self.patrol_speed) * self.patrol_range\n            enemy.y = self.origin_y + math.sin(ilyas.get_time() * self.patrol_speed * 0.7) * self.patrol_range * 0.22\n";
function id(){return Math.random().toString(36).slice(2,10)}function clone(x){return JSON.parse(JSON.stringify(x))}
function fresh(name='My first game',template='Platformer',w=960,h=540,bg='#15171d'){let p={id:id(),name,template,width:w,height:h,bg,grid:32,snap:true,objects:[],assets:[],scripts:[],modified:Date.now()};const add=(type,x,y,extra={})=>p.objects.push(makeObj(type,x,y,extra));if(template==='Platformer'){add('Player',100,390);add('Ground',w/2,h-22,{w:w,h:32});add('Platform',330,405,{w:150});add('Platform',550,325,{w:145});add('Platform',760,245,{w:145});add('Coin',330,360);add('Coin',550,280);add('Coin',760,200);add('Enemy',450, h-62);add('Goal',w-70,h-80)}else if(template==='Top-down adventure'){add('Player',100,100,{behaviors:['topDown','collision']});add('Wall',300,220,{h:200});add('Coin',400,150);add('Enemy',520,300);add('Goal',w-70,h-70)}else if(template==='Endless runner'){add('Player',100,h-100);add('Ground',w/2,h-22,{w:w,h:32});add('Spike',360,h-60);add('Coin',480,h-110);add('Spike',650,h-60);add('Goal',w-60,h-80)}else if(template==='Space shooter'){add('Player',w/2,h-80,{color:'#65c7ff',behaviors:['topDown','collision']});add('Enemy',w/2,100);add('Enemy',w/2-150,160);add('Enemy',w/2+150,160);add('Collectible',w/2,260)}else if(template==='AI Combat Arena'){add('Player',w*.14,h*.5,{color:'#65c7ff',behaviors:['topDown','collision'],health:100,maxHealth:100,speed:210});add('Enemy',w*.68,h*.3,{behaviors:['collision'],health:60,maxHealth:60});add('Enemy',w*.72,h*.68,{behaviors:['collision'],health:60,maxHealth:60});add('Enemy',w*.86,h*.49,{behaviors:['collision'],health:60,maxHealth:60});const ps={id:id(),name:'PlayerCombat',code:playerCombatCode,exports:{speed:210,attack_damage:25,attack_range:92,attack_cooldown:.35},modified:Date.now(),version:1};const es={id:id(),name:'EnemyAIPro',code:enemyAIProCode,exports:{speed:105,detection_range:280,attack_range:42,attack_damage:10,attack_cooldown:.9,max_health:60,patrol_range:90,patrol_speed:1.2},modified:Date.now(),version:1};p.scripts=[ps,es];p.objects.find(o=>o.type==='Player').scriptId=ps.id;p.objects.filter(o=>o.type==='Enemy').forEach(o=>o.scriptId=es.id)}p.modified=Date.now();return p}
function makeObj(type,x,y,extra={}){let d=defs[type]||defs.Rectangle;return {id:id(),type,name:type,x,y,w:d.w,h:d.h,rotation:0,color:d.color,opacity:1,visible:true,layer:0,collision:['Player','Enemy','Platform','Wall','Ground','Moving platform','Spike'].includes(type),speed:180,behaviors:[...d.behaviors],text:type==='Text'?'Your text':type,patrolDistance:100,moveSpeed:80,properties:{},...extra}}
function loadStore(){try{projects=JSON.parse(localStorage.getItem(STORE)||'[]');if(!Array.isArray(projects))projects=[]}catch(e){projects=[];log('Saved project data could not be read. Start a new project or import JSON.','error')}}
function persist(){try{localStorage.setItem(STORE,JSON.stringify(projects));if(project){project.modified=Date.now();let i=projects.findIndex(p=>p.id===project.id);if(i>=0)projects[i]=clone(project);else projects.unshift(clone(project));localStorage.setItem(STORE,JSON.stringify(projects));$('#saveStatus').textContent='Saved locally · '+new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}}catch(e){log('Browser storage is full. Export your project JSON to avoid losing changes.','error')}}
function toast(s){let el=$('#toast');el.textContent=s;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
function log(s,type='info'){let p=document.createElement('p');p.innerHTML='<span class="'+(type==='error'?'console-error':type==='ok'?'console-ok':'console-info')+'">●</span> '+esc(s);$('#console').append(p);$('#console').scrollTop=$('#console').scrollHeight}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function setView(v){$('#dashboard').classList.toggle('hidden',v!=='dash');$('#editor').classList.toggle('hidden',v!=='edit')}
function openProject(p){project=clone(p);selected=null;history=[];future=[];zoom=1;pan={x:0,y:0};setView('edit');$('#projectTitle').textContent=project.name;$('#sceneDimensions').textContent=project.width+' × '+project.height;$('#bgColor').value=project.bg;$('#gridSize').value=String(project.grid||32);$('#snapGrid').checked=project.snap!==false;renderAll();draw();log('Opened project: '+project.name,'ok')}
function renderDashboard(){let root=$('#projectCards');root.innerHTML='';if(!projects.length){root.innerHTML='<div class="project-card" style="grid-column:1/-1;padding:25px;color:#aaa">No saved projects yet. Create one or choose a template below.</div>'}projects.slice().sort((a,b)=>b.modified-a.modified).forEach(p=>{let card=document.createElement('div');card.className='project-card';card.innerHTML='<div class="project-thumb"><div class="thumb-player"></div><div class="thumb-floor"></div><div class="thumb-coin">✦</div></div><div class="project-info"><div class="project-meta"><b>'+esc(p.name)+'</b><div class="card-actions"><button data-a="rename">✎</button><button data-a="duplicate">▣</button><button data-a="delete">×</button></div></div><p>'+esc(p.template||'Empty project')+' · '+new Date(p.modified).toLocaleDateString()+'</p></div>';card.addEventListener('click',e=>{let a=e.target.closest('[data-a]')?.dataset.a;if(!a){openProject(p);return}e.stopPropagation();if(a==='rename')renameProject(p);if(a==='duplicate'){let cp=clone(p);cp.id=id();cp.name=p.name+' Copy';cp.modified=Date.now();projects.push(cp);saveProjects();renderDashboard();toast('Project duplicated')}if(a==='delete'&&confirm('Delete "'+p.name+'" from this browser? This cannot be undone.')){projects=projects.filter(x=>x.id!==p.id);saveProjects();renderDashboard();toast('Project deleted')}});root.append(card)});$('#templates').innerHTML=templates.map(([n,d,i])=>'<div class="template-card" data-template="'+n+'"><div class="template-icon">'+i+'</div><b>'+n+'</b><p>'+d+'</p></div>').join('');$$('.template-card').forEach(el=>el.onclick=()=>showNewModal(el.dataset.template)) }
function saveProjects(){try{localStorage.setItem(STORE,JSON.stringify(projects))}catch(e){toast('Storage full — export projects as JSON')}}
function renameProject(p){modal('Rename project','Give your project a new name.', '<div class="modal-field"><label>Project name</label><input id="modalName" value="'+esc(p.name)+'" maxlength="70"></div>', 'Rename',()=>{let n=$('#modalName').value.trim();if(!n)return false;p.name=n;p.modified=Date.now();if(project?.id===p.id){project.name=n;$('#projectTitle').textContent=n}saveProjects();renderDashboard();toast('Project renamed')})}
function modal(title,desc,fields,ok,onok){$('#modalRoot').innerHTML='<div class="modal-backdrop"><div class="modal"><h2>'+title+'</h2><p>'+desc+'</p>'+fields+'<div class="modal-actions"><button id="modalCancel">Cancel</button><button id="modalOK" class="primary">'+ok+'</button></div></div></div>';$('#modalCancel').onclick=()=>$('#modalRoot').innerHTML='';$('#modalOK').onclick=()=>{if(onok()!==false)$('#modalRoot').innerHTML=''};$('#modalRoot').querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))$('#modalRoot').innerHTML=''}}
function showNewModal(template='Platformer'){modal('Create a project','Set up a new 2D game scene. You can change these settings later.','<div class="modal-field"><label>Project name</label><input id="modalName" value="'+template+' Game" maxlength="70"></div><div class="modal-field"><label>Starter template</label><select id="modalTemplate">'+templates.map(([n])=>'<option '+(n===template?'selected':'')+'>'+n+'</option>').join('')+'</select></div><div class="modal-grid"><div class="modal-field"><label>Canvas width</label><input id="modalW" type="number" min="320" max="1920" value="960"></div><div class="modal-field"><label>Canvas height</label><input id="modalH" type="number" min="240" max="1080" value="540"></div></div><div class="modal-field"><label>Background color</label><input id="modalBg" type="color" value="#15171d"></div>','Create project',()=>{let n=$('#modalName').value.trim();if(!n){toast('Enter a project name');return false}let w=Math.min(1920,Math.max(320,+$('#modalW').value||960)),h=Math.min(1080,Math.max(240,+$('#modalH').value||540));let p=fresh(n,$('#modalTemplate').value,w,h,$('#modalBg').value);projects.unshift(p);saveProjects();openProject(p);renderDashboard();return true})}
function snapshot(){if(!project)return;history.push(JSON.stringify(project.objects));if(history.length>80)history.shift();future=[]}
function undo(){if(!history.length)return;future.push(JSON.stringify(project.objects));project.objects=JSON.parse(history.pop());selected=null;renderAll();draw();persist();log('Undo','ok')}
function redo(){if(!future.length)return;history.push(JSON.stringify(project.objects));project.objects=JSON.parse(future.pop());selected=null;renderAll();draw();persist();log('Redo','ok')}
function addObject(type,x,y){if(!project)return;let o=makeObj(type,x??project.width/2,y??project.height/2);if(type==='Ground'){o.x=project.width/2;o.y=project.height-16;o.w=project.width}if(type==='Background'){o.x=project.width/2;o.y=project.height/2;o.w=project.width;o.h=project.height;o.layer=-100}snapshot();project.objects.push(o);selected=o.id;renderAll();draw();persist();log('Added '+type,'ok')}
function renderAll(){renderHierarchy();renderLibrary();renderInspector();draw();$('#emptyHint').classList.toggle('hidden',project.objects.length>0);$('#undoBtn').disabled=!history.length;$('#redoBtn').disabled=!future.length}
function renderHierarchy(){let root=$('#hierarchy');root.innerHTML='';project.objects.slice().sort((a,b)=>b.layer-a.layer).forEach(o=>{let el=document.createElement('div');el.className='hierarchy-item'+(o.id===selected?' active':'');el.innerHTML='<span class="obj-icon">'+(defs[o.type]?.icon||'▧')+'</span><span>'+esc(o.name)+'</span>';el.onclick=()=>{selected=o.id;renderHierarchy();renderInspector();draw()};root.append(el)})}
function renderLibrary(){let q=$('#assetSearch').value.toLowerCase();$('#objectLibrary').innerHTML=Object.keys(defs).filter(n=>n.toLowerCase().includes(q)).map(n=>'<div draggable="true" class="object-tile" data-type="'+n+'"><span class="tile-icon">'+defs[n].icon+'</span>'+n+'</div>').join('');$$('.object-tile').forEach(el=>{el.onclick=()=>addObject(el.dataset.type);el.addEventListener('dragstart',e=>e.dataTransfer.setData('text/object',el.dataset.type))})}
function renderInspector(){let o=project.objects.find(x=>x.id===selected),root=$('#inspector');$('#selectedTag').textContent=o?o.type.toUpperCase():'NO SELECTION';$('#selectionInfo').textContent=o?o.name+' · '+Math.round(o.x)+', '+Math.round(o.y):'No selection';if(!o){root.innerHTML='<div class="inspector-empty"><div>◈</div><b>Nothing selected</b><p>Select an object in the scene to edit its properties.</p></div>';return}
const field=(label,key,val,type='number')=>'<div class="field-row"><label class="field-label">'+label+'</label><input class="field-input" data-prop="'+key+'" type="'+type+'" value="'+esc(val)+'" '+(type==='number'?'step="1"':'')+'></div>';
root.innerHTML='<div class="field-group"><div class="field-heading">Identity</div>'+field('Object name','name',o.name,'text')+field('Object type','type',o.type,'text')+(o.type==='Text'?field('Displayed text','text',o.text||'Your text','text'):'')+'</div><div class="field-group"><div class="field-heading">Transform</div><div class="field-grid">'+field('Position X','x',Math.round(o.x))+field('Position Y','y',Math.round(o.y))+field('Width','w',Math.round(o.w))+field('Height','h',Math.round(o.h))+'</div>'+field('Rotation (°)','rotation',o.rotation)+'</div><div class="field-group"><div class="field-heading">Appearance</div><label class="field-label">Color</label><input class="color-field" data-prop="color" type="color" value="'+o.color+'"><div style="margin-top:10px">'+field('Opacity (0–1)','opacity',o.opacity,'number')+'</div><div class="field-grid">'+field('Layer order','layer',o.layer)+field('Speed','speed',o.speed)+'</div><label class="field-label"><input class="field-check" data-prop="visible" type="checkbox" '+(o.visible?'checked':'')+'> Visible</label><label class="field-label" style="margin-top:8px"><input class="field-check" data-prop="collision" type="checkbox" '+(o.collision?'checked':'')+'> Solid collision</label></div><div class="field-group"><div class="field-heading">Behaviors</div><div id="behaviors">'+Object.keys(behaviorLabels).map(k=>'<label class="field-label" style="margin:9px 0"><input type="checkbox" class="field-check" data-behavior="'+k+'" '+(o.behaviors.includes(k)?'checked':'')+'> '+behaviorLabels[k]+'</label>').join('')+'</div>'+((o.behaviors.includes('patrol')||o.behaviors.includes('moveBetween'))?field('Patrol distance','patrolDistance',o.patrolDistance)+field('Move speed','moveSpeed',o.moveSpeed):'')+'</div><div class="inspector-actions"><button id="duplicateObj">▣ Duplicate</button><button id="deleteObj">× Delete</button></div>';
root.querySelectorAll('[data-prop]').forEach(el=>{el.addEventListener('change',()=>{snapshot();let k=el.dataset.prop,v=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;if(k==='type'&&!defs[v]){toast('Use a type from the object library');renderInspector();return}o[k]=v;if(k==='type'){let d=defs[v];o.color=d.color;o.w=d.w;o.h=d.h;o.behaviors=[...d.behaviors]}renderHierarchy();renderInspector();draw();persist()});if(el.type==='number')el.addEventListener('keydown',e=>{if(e.key==='Enter')el.blur()})});root.querySelectorAll('[data-behavior]').forEach(el=>el.onchange=()=>{snapshot();if(el.checked&&!o.behaviors.includes(el.dataset.behavior))o.behaviors.push(el.dataset.behavior);else o.behaviors=o.behaviors.filter(b=>b!==el.dataset.behavior);persist();log((el.checked?'Enabled ':'Disabled ')+behaviorLabels[el.dataset.behavior]+' on '+o.name);renderInspector()});$('#duplicateObj').onclick=()=>duplicateSelected();$('#deleteObj').onclick=()=>deleteSelected()}
const behaviorLabels={platformer:'Platformer movement',topDown:'Top-down movement',gravity:'Gravity',collision:'Solid collision',collectCoin:'Collect for score',followPlayer:'Follow player',patrol:'Patrol between points',moveBetween:'Move between positions',damagePlayer:'Damage player',checkpoint:'Checkpoint',win:'Reach goal to win',displayText:'Display text',restart:'Restart level'};
function draw(){if(!project)return;let c=$('#gameCanvas'),ctx=c.getContext('2d');c.width=project.width;c.height=project.height;ctx.clearRect(0,0,c.width,c.height);ctx.fillStyle=project.bg;ctx.fillRect(0,0,c.width,c.height);if(showGrid){ctx.strokeStyle='#ffffff0b';ctx.lineWidth=1;ctx.beginPath();for(let x=0;x<c.width;x+=(project.grid||32)){ctx.moveTo(x,0);ctx.lineTo(x,c.height)}for(let y=0;y<c.height;y+=(project.grid||32)){ctx.moveTo(0,y);ctx.lineTo(c.width,y)}ctx.stroke()}
project.objects.slice().filter(o=>o.visible).sort((a,b)=>a.layer-b.layer).forEach(o=>drawObj(ctx,o));if(selected){let o=project.objects.find(x=>x.id===selected);if(o){ctx.save();ctx.translate(o.x,o.y);ctx.rotate((o.rotation||0)*Math.PI/180);ctx.strokeStyle='#ff5968';ctx.lineWidth=2;ctx.setLineDash([5,3]);ctx.strokeRect(-o.w/2-4,-o.h/2-4,o.w+8,o.h+8);ctx.setLineDash([]);ctx.fillStyle='#ff5968';[[-o.w/2-4,-o.h/2-4],[o.w/2+4,-o.h/2-4],[-o.w/2-4,o.h/2+4],[o.w/2+4,o.h/2+4]].forEach(([x,y])=>ctx.fillRect(x-3,y-3,6,6));ctx.restore()}}}
function drawObj(ctx,o){ctx.save();ctx.globalAlpha=Math.max(0,Math.min(1,Number(o.opacity??1)));ctx.translate(o.x,o.y);ctx.rotate((o.rotation||0)*Math.PI/180);ctx.fillStyle=o.color||'#ff4657';ctx.strokeStyle=o.color||'#ff4657';let w=o.w,h=o.h;if(o.assetData){let im=assetCache[o.id];if(!im){im=new Image();assetCache[o.id]=im;im.onload=()=>draw();im.src=o.assetData}if(im.complete&&im.naturalWidth){ctx.drawImage(im,-w/2,-h/2,w,h);ctx.restore();return}}switch(o.type){case'Circle':case'Coin':case'Collectible':ctx.beginPath();ctx.arc(0,0,Math.min(w,h)/2,0,Math.PI*2);ctx.fill();if(o.type!=='Circle'){ctx.strokeStyle='#fff8';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,Math.min(w,h)*.31,0,Math.PI*2);ctx.stroke()}break;case'Spike':ctx.beginPath();ctx.moveTo(-w/2,h/2);ctx.lineTo(0,-h/2);ctx.lineTo(w/2,h/2);ctx.closePath();ctx.fill();break;case'Goal':case'Checkpoint':ctx.fillRect(-w/2,-h/2,4,h);ctx.fillRect(-w/2+4,-h/2,w*.8,h*.4);break;case'Text':ctx.font=Math.max(12,h*.6)+'px Manrope,Arial';ctx.textBaseline='middle';ctx.fillText(o.text||o.name,-w/2,-h*.05);break;case'Background':ctx.fillRect(-w/2,-h/2,w,h);break;case'Player':ctx.beginPath();ctx.roundRect(-w/2,-h/2,w,h,5);ctx.fill();ctx.fillStyle='#fff';ctx.fillRect(-w*.22,-h*.2,4,4);ctx.fillRect(w*.08,-h*.2,4,4);break;default:ctx.beginPath();ctx.roundRect(-w/2,-h/2,w,h,Math.min(5,w/8,h/8));ctx.fill();if(['Platform','Ground','Wall','Moving platform'].includes(o.type)){ctx.fillStyle='#ffffff18';ctx.fillRect(-w/2,-h/2,w,Math.min(4,h))}}ctx.restore()}
function canvasPoint(e){let r=$('#gameCanvas').getBoundingClientRect();return {x:(e.clientX-r.left)*project.width/r.width,y:(e.clientY-r.top)*project.height/r.height}}
function hit(p){return project.objects.slice().sort((a,b)=>b.layer-a.layer).find(o=>o.visible&&Math.abs(p.x-o.x)<=o.w/2+4&&Math.abs(p.y-o.y)<=o.h/2+4)}
function canvasDown(e){if(!project)return;let p=canvasPoint(e);if(tool==='rect'||tool==='circle'||tool==='text'){let type=tool==='rect'?'Rectangle':tool==='circle'?'Circle':'Text';addObject(type,p.x,p.y);tool='select';$$('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===tool));return}let picked=project.objects.find(x=>x.id===selected&&x.visible);if(picked){const hs=[[-1,-1],[1,-1],[-1,1],[1,1]];for(const [hx,hy] of hs){const px=picked.x+hx*(picked.w/2+4),py=picked.y+hy*(picked.h/2+4);if(Math.abs(p.x-px)<10&&Math.abs(p.y-py)<10){snapshot();drag={id:picked.id,mode:'resize',start:p,ox:picked.x,oy:picked.y,ow:picked.w,oh:picked.h,hx,hy,moved:false};$('#gameCanvas').setPointerCapture?.(e.pointerId);return}}}let o=hit(p);if(o){selected=o.id;renderHierarchy();renderInspector();draw();snapshot();drag={id:o.id,mode:'move',start:p,ox:o.x,oy:o.y,moved:false};$('#gameCanvas').setPointerCapture?.(e.pointerId)}else{selected=null;renderAll()}}
function canvasMove(e){if(!drag)return;let p=canvasPoint(e),o=project.objects.find(x=>x.id===drag.id);if(!o)return;let dx=p.x-drag.start.x,dy=p.y-drag.start.y;if(Math.abs(dx)+Math.abs(dy)>1)drag.moved=true;if(drag.mode==='resize'){o.w=Math.max(8,drag.ow+dx*drag.hx);o.h=Math.max(8,drag.oh+dy*drag.hy);o.x=drag.ox+dx/2;o.y=drag.oy+dy/2;if($('#snapGrid').checked){let g=project.grid||32;o.w=Math.max(8,Math.round(o.w/g)*g);o.h=Math.max(8,Math.round(o.h/g)*g)}}else{o.x=drag.ox+dx;o.y=drag.oy+dy;if($('#snapGrid').checked){let s=project.grid||32;o.x=Math.round(o.x/s)*s;o.y=Math.round(o.y/s)*s}}draw();renderInspector()}
function canvasUp(){if(drag){if(drag.moved){persist();renderHierarchy();log((drag.mode==='resize'?'Resized ':'Moved ')+(project.objects.find(o=>o.id===drag.id)?.name||'object'),'ok')}else{history.pop()}drag=null}}
function deleteSelected(){if(!selected)return;let o=project.objects.find(x=>x.id===selected);if(!o)return;snapshot();project.objects=project.objects.filter(x=>x.id!==selected);selected=null;renderAll();persist();log('Deleted '+o.name,'ok')}
function duplicateSelected(){let o=project.objects.find(x=>x.id===selected);if(!o)return;snapshot();let cp=clone(o);cp.id=id();cp.name=o.name+' Copy';cp.x+=25;cp.y+=25;project.objects.push(cp);selected=cp.id;renderAll();persist();log('Duplicated '+o.name,'ok')}
function setTool(t){tool=t;$$('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===t));$('#gameCanvas').style.cursor=t==='select'?'default':'crosshair'}
function saveCurrent(){persist();renderDashboard();toast('Project saved in this browser');log('Project saved locally','ok')}
function download(name,blob){let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),2000)}
function exportJSON(){if(!project)return;download(project.name.replace(/[^a-z0-9-_]/gi,'_')+'.json',new Blob([JSON.stringify({format:'ilyas-studio-project',version:2,project},null,2)],{type:'application/json'}));toast('Project JSON exported');log('Exported project JSON','ok')}
function importJSONFile(file){let reader=new FileReader();reader.onload=()=>{try{let data=JSON.parse(reader.result),p=data.project||data;if(!p||!Array.isArray(p.objects)||!p.width||!p.height)throw Error('This file is not a valid Ilyas Studio project.');p.id=id();p.name=(p.name||'Imported project')+' (Imported)';p.modified=Date.now();p.objects=p.objects.map(o=>({...makeObj(o.type||'Rectangle',o.x||0,o.y||0),...o,id:id()}));projects.unshift(p);saveProjects();renderDashboard();openProject(p);toast('Project imported successfully')}catch(e){toast('Import failed: '+e.message);log('JSON import failed: '+e.message,'error')}};reader.readAsText(file)}
function importImage(file){if(!file)return;let reader=new FileReader();reader.onload=()=>{let im=new Image();im.onload=()=>{let type='Custom sprite';let o=makeObj(type,project.width/2,project.height/2,{w:Math.min(im.width,300),h:Math.min(im.height,300),assetData:reader.result,assetName:file.name,collision:false});snapshot();project.objects.push(o);selected=o.id;renderAll();draw();persist();log('Imported image: '+file.name,'ok')};im.src=reader.result};reader.readAsDataURL(file)}
function drawObjPlay(ctx,o){ctx.save();ctx.globalAlpha=o.opacity??1;ctx.translate(o.x,o.y);ctx.rotate((o.rotation||0)*Math.PI/180);if(o.assetData){let im=assetCache[o.id];if(!im){im=new Image();im.src=o.assetData;assetCache[o.id]=im}if(im.complete&&im.naturalWidth)ctx.drawImage(im,-o.w/2,-o.h/2,o.w,o.h);else{ctx.fillStyle=o.color;ctx.fillRect(-o.w/2,-o.h/2,o.w,o.h)}ctx.restore();return}ctx.fillStyle=o.color||'#aaa';let w=o.w,h=o.h;if(o.type==='Text'){ctx.font=Math.max(12,h*.6)+'px Arial';ctx.fillText(o.text||o.name,-w/2,0)}else if(['Circle','Coin','Collectible'].includes(o.type)){ctx.beginPath();ctx.arc(0,0,Math.min(w,h)/2,0,Math.PI*2);ctx.fill()}else if(o.type==='Spike'){ctx.beginPath();ctx.moveTo(-w/2,h/2);ctx.lineTo(0,-h/2);ctx.lineTo(w/2,h/2);ctx.fill()}else if(o.type==='Goal'||o.type==='Checkpoint'){ctx.fillRect(-w/2,-h/2,4,h);ctx.fillRect(-w/2+4,-h/2,w*.8,h*.4)}else{ctx.beginPath();ctx.roundRect(-w/2,-h/2,w,h,4);ctx.fill()}ctx.restore()}
let raf=0,lastTime=0,assetCache={};function startGame(){if(running||!project)return;running=true;let objs=clone(project.objects.filter(o=>o.visible)).map(o=>({...o,vx:0,vy:0,startX:o.x,startY:o.y,alive:true,health:Number(o.health??100),maxHealth:Number(o.maxHealth??100)}));game={objects:objs,score:0,won:false,lost:false,paused:false,checkpoint:null,scriptContacts:new Set(),blockState:{},message:'',messageUntil:0};$('#playOverlay').classList.remove('hidden');$('#playBtn').disabled=true;$('#stopBtn').disabled=false;$('#playScore').textContent='Score: 0';lastTime=performance.now();log('Playtest started','ok');raf=requestAnimationFrame(gameFrame)}
function stopGame(){if(!running)return;running=false;cancelAnimationFrame(raf);$('#playOverlay').classList.add('hidden');$('#playBtn').disabled=false;$('#stopBtn').disabled=true;game=null;keys={};log('Playtest stopped. Editor scene is unchanged.','ok')}
function restartGame(){stopGame();startGame()}
function runVisualBlocks(objs,dt,now){
 if(!game)return;
 for(const o of objs){
  const bs=Array.isArray(o.visualBlocks)?o.visualBlocks:[];
  if(!bs.length)continue;
  const st=game.blockState[o.id]||(game.blockState[o.id]={done:{},waits:{}});
  for(const b of bs){
   if(b.type==='start'){st.done[b.uid]=true;continue}
   if(['score','color','speed','say'].includes(b.type)&&st.done[b.uid])continue;
   if(b.type==='score'){game.score+=Math.max(1,Math.min(100000,Number(b.value)||10));$('#playScore').textContent='Score: '+game.score;st.done[b.uid]=true;continue}
   if(b.type==='color'){o.color=b.value||o.color;st.done[b.uid]=true;continue}
   if(b.type==='speed'){o.speed=Math.max(1,Math.min(1000,Number(b.value)||180));st.done[b.uid]=true;continue}
   if(b.type==='say'){game.message=String(b.value||'');game.messageUntil=now+2600;st.done[b.uid]=true;continue}
   if(b.type==='wait'){
    if(st.waits[b.uid]===undefined)st.waits[b.uid]=Math.max(.1,Math.min(3600,Number(b.value)||1));
    if(st.waits[b.uid]>0){st.waits[b.uid]=Math.max(0,st.waits[b.uid]-dt);break}
    continue;
   }
   if(b.type==='right')o.x=Math.min(project.width-o.w/2,o.x+(Number(o.speed)||180)*dt);
   else if(b.type==='left')o.x=Math.max(o.w/2,o.x-(Number(o.speed)||180)*dt);
   else if(b.type==='up')o.y=Math.max(o.h/2,o.y-(Number(o.speed)||180)*dt);
   else if(b.type==='down')o.y=Math.min(project.height-o.h/2,o.y+(Number(o.speed)||180)*dt);
   else if(b.type==='keyright'&&(keys.ArrowRight||keys.d))o.x=Math.min(project.width-o.w/2,o.x+(Number(o.speed)||180)*dt);
   else if(b.type==='keyleft'&&(keys.ArrowLeft||keys.a))o.x=Math.max(o.w/2,o.x-(Number(o.speed)||180)*dt);
  }
 }
}
function applyTouchBlocks(a,b){
 if(!game)return;
 for(const [owner,other] of [[a,b],[b,a]]){
  for(const block of (Array.isArray(owner.visualBlocks)?owner.visualBlocks:[])){
   if(block.type==='if_touch'&&block.target&&block.target===other.name){
    const amount=Math.max(1,Math.min(100000,Number(block.value)||1));
    game.score+=amount;$('#playScore').textContent='Score: '+game.score;
    game.message=owner.name+' touched '+other.name+'! +'+amount;
    game.messageUntil=performance.now()+1800;
   }
  }
 }
}
function gameFrame(now){
 if(!running||!game)return;
 let dt=Math.min(.033,(now-lastTime)/1000||0);lastTime=now;
 const c=$('#playCanvas'),ctx=c.getContext('2d');c.width=project.width;c.height=project.height;ctx.fillStyle=project.bg;ctx.fillRect(0,0,c.width,c.height);
 let objs=game.objects.filter(o=>o.alive),player=objs.find(o=>o.type==='Player');
 if(player){player.health=Number(player.health??100);player.maxHealth=Number(player.maxHealth??100);$('#playHealth').textContent='HP: '+Math.max(0,Math.ceil(player.health))+' / '+Math.ceil(player.maxHealth);if(player.health<=0)game.lost=true}
 else $('#playHealth').textContent='HP: —';
 if(!game.won&&!game.lost&&!game.paused){
  if(player){
   let top=player.behaviors.includes('topDown');
   if(top){
    if(!player.scriptId&&!(player.visualBlocks||[]).length){player.vx=((keys.ArrowRight||keys.d?1:0)-(keys.ArrowLeft||keys.a?1:0))*player.speed;player.vy=((keys.ArrowDown||keys.s?1:0)-(keys.ArrowUp||keys.w?1:0))*player.speed}
    player.x+=player.vx*dt;player.y+=player.vy*dt;
   }else{
    if(!player.scriptId&&!(player.visualBlocks||[]).length)player.vx=((keys.ArrowRight||keys.d?1:0)-(keys.ArrowLeft||keys.a?1:0))*player.speed;
    player.x+=player.vx*dt;
    if(player.behaviors.includes('gravity')){player.vy=(player.vy||0)+720*dt;player.y+=player.vy*dt}
    if(!player.scriptId&&!(player.visualBlocks||[]).length&&(keys.Space||keys.ArrowUp||keys.w)&&player.onGround){player.vy=-360;player.y-=2;player.onGround=false;keys.Space=false;keys.ArrowUp=false;keys.w=false}
   }
   player.x=Math.max(player.w/2,Math.min(project.width-player.w/2,player.x));
   if(player.y>project.height+100)game.lost=true;
  }
  for(const o of objs){if(o!==player&&(o.behaviors.includes('patrol')||o.behaviors.includes('moveBetween'))){o.x=o.startX+Math.sin(now/1000*(o.moveSpeed||80)/80)*(o.patrolDistance||100)}}
  runVisualBlocks(objs,dt,now);
  for(let i=0;i<objs.length;i++)for(let j=i+1;j<objs.length;j++){
   const a=objs[i],b=objs[j];if(!a.alive||!b.alive)continue;
   const touching=Math.abs(a.x-b.x)<(a.w+b.w)/2-2&&Math.abs(a.y-b.y)<(a.h+b.h)/2-2;
   const key=[a.id,b.id].sort().join(':');if(touching){if(!game.scriptContacts.has(key)){game.scriptContacts.add(key);applyTouchBlocks(a,b)}}else game.scriptContacts.delete(key);
  }
  if(player){
   for(const o of objs){
    if(o===player||!o.alive)continue;
    const overlap=Math.abs(player.x-o.x)<(player.w+o.w)/2-2&&Math.abs(player.y-o.y)<(player.h+o.h)/2-2;
    if(!overlap)continue;
    if(o.collision&&['Platform','Ground','Wall','Moving platform'].includes(o.type)&&player.vy>=0&&player.y-player.h/2<o.y){player.y=o.y-o.h/2-player.h/2;player.vy=0;player.onGround=true}
    else if(o.behaviors.includes('collectCoin')&&o.alive){o.alive=false;game.score+=1;$('#playScore').textContent='Score: '+game.score}
    else if(o.behaviors.includes('damagePlayer'))game.lost=true;
    else if(o.behaviors.includes('win'))game.won=true;
    else if(o.behaviors.includes('checkpoint'))game.checkpoint={x:player.x,y:player.y};
   }
   if(player.y+player.h/2>=project.height){player.y=project.height-player.h/2;player.vy=0;player.onGround=true}
  }
 }
 objs.filter(o=>o.alive).sort((a,b)=>a.layer-b.layer).forEach(o=>drawObjPlay(ctx,o));
 if(game.message&&now<game.messageUntil){ctx.save();ctx.font='bold 18px Arial';ctx.textAlign='center';const mw=Math.min(c.width-40,ctx.measureText(game.message).width+32);ctx.fillStyle='#16131de8';ctx.fillRect((c.width-mw)/2,16,mw,42);ctx.fillStyle='#fff';ctx.fillText(game.message,c.width/2,43);ctx.restore()}
 if(game.won||game.lost){ctx.fillStyle='#08090bdc';ctx.fillRect(0,0,c.width,c.height);ctx.textAlign='center';ctx.fillStyle=game.won?'#53d6a1':'#ff5968';ctx.font='bold 42px Arial';ctx.fillText(game.won?'LEVEL COMPLETE!':'GAME OVER',c.width/2,c.height/2);ctx.fillStyle='#eee';ctx.font='16px Arial';ctx.fillText('Score: '+game.score+'  ·  Click Restart to play again',c.width/2,c.height/2+35)}
 else if(game.paused){ctx.fillStyle='#08090ba8';ctx.fillRect(0,0,c.width,c.height);ctx.textAlign='center';ctx.fillStyle='#fff';ctx.font='bold 40px Arial';ctx.fillText('PAUSED',c.width/2,c.height/2)}
 raf=requestAnimationFrame(gameFrame)
}
function exportGame(){if(!project)return;const p=clone(project);if(p.objects.some(o=>Array.isArray(o.visualBlocks)&&o.visualBlocks.length))log('Export note: visual-block logic runs in the editor playtest; standalone HTML export does not include the block runtime yet. Keep the project JSON to preserve your blocks.','error');const runtime=`<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(p.name)}</title><style>*{box-sizing:border-box}body{margin:0;background:#101012;color:#eee;font:13px Arial;display:flex;min-height:100vh;align-items:center;justify-content:center;flex-direction:column;gap:12px}canvas{width:min(960px,96vw);max-height:78vh;aspect-ratio:${p.width}/${p.height};border:1px solid #333;background:${p.bg}}p{color:#999;font-size:11px}</style></head><body><canvas id="g" width="${p.width}" height="${p.height}"></canvas><p>Move: A/D or arrows · Jump: Space/W/↑ · R: Restart</p><script>const P=${JSON.stringify(p)};const c=document.querySelector('#g'),x=c.getContext('2d');let os=P.objects.filter(o=>o.visible).map(o=>({...o,vx:0,vy:0,sx:o.x,sy:o.y,alive:true})),keys={},score=0,done='',last=performance.now();onkeydown=e=>{keys[e.key]=true;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();if(e.key.toLowerCase()==='r')location.reload()};onkeyup=e=>keys[e.key]=false;function frame(t){let dt=Math.min(.033,(t-last)/1000);last=t;x.fillStyle=P.bg;x.fillRect(0,0,c.width,c.height);let player=os.find(o=>o.type==='Player');if(player&&!done){let top=player.behaviors.includes('topDown');player.vx=((keys.ArrowRight||keys.d?1:0)-(keys.ArrowLeft||keys.a?1:0))*player.speed;if(top){player.vy=((keys.ArrowDown||keys.s?1:0)-(keys.ArrowUp||keys.w?1:0))*player.speed;player.y+=player.vy*dt}else{player.vy=(player.vy||0)+(player.behaviors.includes('gravity')?720*dt:0);if((keys[' ']||keys.ArrowUp||keys.w)&&player.ground){player.vy=-360;player.ground=false}player.y+=player.vy*dt}player.x+=player.vx*dt;player.x=Math.max(player.w/2,Math.min(P.width-player.w/2,player.x));for(const o of os){if(!o.alive||o===player)continue;if(o.behaviors.includes('patrol')||o.behaviors.includes('moveBetween'))o.x=o.sx+Math.sin(t/1000*(o.moveSpeed||80)/80)*(o.patrolDistance||100);if(Math.abs(player.x-o.x)<(player.w+o.w)/2-2&&Math.abs(player.y-o.y)<(player.h+o.h)/2-2){if(o.collision&&['Platform','Ground','Wall','Moving platform'].includes(o.type)&&player.vy>=0&&player.y-player.h/2<o.y){player.y=o.y-o.h/2-player.h/2;player.vy=0;player.ground=true}else if(o.behaviors.includes('collectCoin')){o.alive=false;score++}else if(o.behaviors.includes('damagePlayer'))done='GAME OVER';else if(o.behaviors.includes('win'))done='LEVEL COMPLETE'}}if(player.y+player.h/2>=P.height){player.y=P.height-player.h/2;player.vy=0;player.ground=true}if(player.y>P.height+80)done='GAME OVER'}for(const o of os){if(!o.alive)continue;x.save();x.globalAlpha=o.opacity??1;x.translate(o.x,o.y);x.rotate((o.rotation||0)*Math.PI/180);x.fillStyle=o.color||'#aaa';let w=o.w,h=o.h;if(['Coin','Collectible','Circle'].includes(o.type)){x.beginPath();x.arc(0,0,Math.min(w,h)/2,0,Math.PI*2);x.fill()}else if(o.type==='Spike'){x.beginPath();x.moveTo(-w/2,h/2);x.lineTo(0,-h/2);x.lineTo(w/2,h/2);x.fill()}else if(o.type==='Text'){x.font=Math.max(12,h*.6)+'px Arial';x.fillText(o.text||o.name,-w/2,0)}else{x.fillRect(-w/2,-h/2,w,h)}x.restore()}x.fillStyle='#ffcc68';x.font='14px Arial';x.fillText('Score: '+score,15,24);if(done){x.fillStyle='#000b';x.fillRect(0,0,c.width,c.height);x.textAlign='center';x.fillStyle=done==='GAME OVER'?'#ff5968':'#53d6a1';x.font='bold 40px Arial';x.fillText(done,c.width/2,c.height/2);x.textAlign='left'}requestAnimationFrame(frame)}requestAnimationFrame(frame);<\/script></body></html>`;download(p.name.replace(/[^a-z0-9-_]/gi,'_')+'-game.html',new Blob([runtime],{type:'text/html'}));toast('Playable HTML exported');log('Exported standalone playable HTML game','ok')}
function exportZip(){if(!project)return;const p=clone(project);if((p.scripts||[]).length)log('Export note: Python source files will be included in the ZIP, but the standalone game runtime does not execute Python scripts yet.','error');const html='<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(p.name)+'</title><link rel="stylesheet" href="style.css"></head><body><main><canvas id="game" width="'+p.width+'" height="'+p.height+'"></canvas><p>Move: A/D or arrows · Jump: Space / W / ↑ · R: restart</p></main><script src="game.js"></script></body></html>';const css='body{margin:0;background:#101012;color:#ddd;font:13px Arial;min-height:100vh;display:grid;place-items:center}main{text-align:center}canvas{display:block;width:min(960px,96vw);height:auto;border:1px solid #333}p{color:#888}';const js='const P='+JSON.stringify(p)+';const c=document.querySelector("#game"),x=c.getContext("2d");let os=P.objects.filter(o=>o.visible).map(o=>({...o,vy:0,alive:true})),keys={},score=0,done="";onkeydown=e=>{keys[e.key]=true;if(e.key.toLowerCase()==="r")location.reload()};onkeyup=e=>keys[e.key]=false;function frame(){x.fillStyle=P.bg;x.fillRect(0,0,c.width,c.height);let p=os.find(o=>o.type==="Player");if(p&&!done){p.vx=((keys.ArrowRight||keys.d?1:0)-(keys.ArrowLeft||keys.a?1:0))*p.speed;if(p.behaviors.includes("topDown"))p.y+=((keys.ArrowDown||keys.s?1:0)-(keys.ArrowUp||keys.w?1:0))*p.speed/60;else{p.vy+=p.behaviors.includes("gravity")?.65:0;if((keys[" "]||keys.ArrowUp||keys.w)&&p.ground){p.vy=-9;p.ground=false}p.y+=p.vy}p.x+=p.vx/60;for(let o of os){if(o===p||!o.alive)continue;if(Math.abs(p.x-o.x)<(p.w+o.w)/2&&Math.abs(p.y-o.y)<(p.h+o.h)/2){if(o.collision&&["Ground","Platform","Wall","Moving platform"].includes(o.type)&&p.vy>=0&&p.y<o.y){p.y=o.y-o.h/2-p.h/2;p.vy=0;p.ground=true}else if(o.behaviors.includes("collectCoin")){o.alive=false;score++}else if(o.behaviors.includes("damagePlayer"))done="GAME OVER";else if(o.behaviors.includes("win"))done="LEVEL COMPLETE"}}if(p.y+p.h/2>=P.height){p.y=P.height-p.h/2;p.vy=0;p.ground=true}if(p.y>P.height+80)done="GAME OVER"}for(let o of os){if(!o.alive)continue;x.save();x.fillStyle=o.color;x.translate(o.x,o.y);x.rotate((o.rotation||0)*Math.PI/180);if(["Coin","Circle","Collectible"].includes(o.type)){x.beginPath();x.arc(0,0,Math.min(o.w,o.h)/2,0,7);x.fill()}else if(o.type==="Spike"){x.beginPath();x.moveTo(-o.w/2,o.h/2);x.lineTo(0,-o.h/2);x.lineTo(o.w/2,o.h/2);x.fill()}else if(o.type==="Text"){x.font="20px Arial";x.fillText(o.text||o.name,-o.w/2,0)}else x.fillRect(-o.w/2,-o.h/2,o.w,o.h);x.restore()}x.fillStyle="#ffcc68";x.fillText("Score: "+score,12,20);if(done){x.fillStyle="#000b";x.fillRect(0,0,c.width,c.height);x.fillStyle="#fff";x.font="bold 36px Arial";x.textAlign="center";x.fillText(done,c.width/2,c.height/2)}requestAnimationFrame(frame)}requestAnimationFrame(frame);';const files={'index.html':html,'style.css':css,'game.js':js,'project.json':JSON.stringify({format:'ilyas-studio-project',version:2,project:p},null,2),'README.txt':'ILYAS STUDIO — EXPORTED GAME\n\nOpen index.html in a modern browser to play. No server or account is required.\nControls: A/D or arrow keys to move; Space, W, or Up to jump; R to restart.\nEdit project.json to inspect the scene data. This is a standalone HTML5 canvas game.'};for(const s of (p.scripts||[])){const safe=(s.name||'script').replace(/[^a-z0-9_-]/gi,'_');files['scripts/'+safe+'.py']=s.code||''}files['README.txt']+='\\nVisual block scripts are saved in project JSON; the standalone HTML export does not include the block runtime yet.';const blob=makeZip(files);download(p.name.replace(/[^a-z0-9-_]/gi,'_')+'-export.zip',blob);toast('Game ZIP exported');log('Created standalone HTML5 ZIP export','ok')}
function makeZip(files){const enc=new TextEncoder(),chunks=[],central=[];let offset=0;function crc32(data){let crc=-1;for(let b of data){crc^=b;for(let k=0;k<8;k++)crc=(crc>>>1)^((crc&1)?0xedb88320:0)}return (crc^-1)>>>0}function u16(n){return [n&255,(n>>>8)&255]}function u32(n){return [n&255,(n>>>8)&255,(n>>>16)&255,(n>>>24)&255]}for(const [name,content] of Object.entries(files)){const n=enc.encode(name),d=enc.encode(content),crc=crc32(d),head=new Uint8Array([...u32(0x04034b50),...u16(20),...u16(0),...u16(0),...u16(0),...u16(0),...u32(crc),...u32(d.length),...u32(d.length),...u16(n.length),...u16(0),...n]);chunks.push(head,d);central.push(new Uint8Array([...u32(0x02014b50),...u16(20),...u16(20),...u16(0),...u16(0),...u16(0),...u16(0),...u32(crc),...u32(d.length),...u32(d.length),...u16(n.length),...u16(0),...u16(0),...u16(0),...u16(0),...u32(0),...u32(offset),...n]));offset+=head.length+d.length}let csize=central.reduce((a,b)=>a+b.length,0),end=new Uint8Array([...u32(0x06054b50),...u16(0),...u16(0),...u16(central.length),...u16(central.length),...u32(csize),...u32(offset),...u16(0)]);return new Blob([...chunks,...central,end],{type:'application/zip'})}
function tutorial(){modal('Quick start guide','Create your first playable 2D game in a few steps.','<div style="color:#bbb;line-height:2;font-size:12px"><b style="color:#ff727d">01</b> Add objects from the left Object Library.<br><b style="color:#ff727d">02</b> Drag them in the canvas to position them.<br><b style="color:#ff727d">03</b> Select an object and adjust its properties on the right.<br><b style="color:#ff727d">04</b> Enable behaviors like Gravity or Collect for score.<br><b style="color:#ff727d">05</b> Press Play to test, then Save and Export.<br><br><span style="color:#888">Tip: use WASD or arrow keys to move, Space to jump. Projects are stored in this browser.</span></div>','Got it',()=>true)}
function bind(){ $('#importProjectBtn').onclick=()=>$('#projectJsonFile').click();$('#projectJsonFile').onchange=e=>{const f=e.target.files[0];if(f)importJSONFile(f);e.target.value=''};$('#newProjectBtn').onclick=()=>showNewModal();$('#backBtn').onclick=()=>{saveCurrent();setView('dash');renderDashboard()};$('#saveBtn').onclick=saveCurrent;$('#playBtn').onclick=startGame;$('#stopBtn').onclick=stopGame;$('#exitPlayBtn').onclick=stopGame;$('#restartBtn').onclick=restartGame;$('#exportBtn').onclick=()=>modal('Export your game','Choose a format. The standalone HTML opens directly; ZIP includes the game runtime, scene data, and README.','<div class="modal-field"><label>Export format</label><select id="exportKind"><option value="zip">Playable HTML5 ZIP (recommended)</option><option value="html">Single playable HTML file</option><option value="json">Project JSON (backup / sharing)</option></select></div>','Export',()=>{let v=$('#exportKind').value;v==='zip'?exportZip():v==='html'?exportGame():exportJSON()});$('#tutorialBtn').onclick=tutorial;$('#addObjectBtn').onclick=()=>modal('Add an object','Choose a built-in object to place in the center of your scene.','<div class="modal-field"><label>Object</label><select id="addType">'+Object.keys(defs).map(n=>'<option>'+n+'</option>').join('')+'</select></div>','Add object',()=>addObject($('#addType').value));$('#assetSearch').oninput=renderLibrary;$('#importAssetBtn').onclick=()=>$('#assetFile').click();$('#assetFile').onchange=e=>{if(e.target.files[0])importImage(e.target.files[0]);e.target.value=''};$('#bgColor').onchange=e=>{project.bg=e.target.value;draw();persist()};$('#gridSize').onchange=e=>{project.grid=+e.target.value;draw();persist()};$('#snapGrid').onchange=e=>{project.snap=e.target.checked;persist()};$('#undoBtn').onclick=undo;$('#redoBtn').onclick=redo;$('#gridBtn').onclick=()=>{showGrid=!showGrid;$('#gridBtn').classList.toggle('active',showGrid);draw()};$('#zoomInBtn').onclick=()=>{zoom=Math.min(2,zoom+.1);$('#zoomLabel').textContent=Math.round(zoom*100)+'%';$('#gameCanvas').style.transform='scale('+zoom+')'};$('#zoomOutBtn').onclick=()=>{zoom=Math.max(.5,zoom-.1);$('#zoomLabel').textContent=Math.round(zoom*100)+'%';$('#gameCanvas').style.transform='scale('+zoom+')'};$$('[data-tool]').forEach(b=>b.onclick=()=>setTool(b.dataset.tool));$('#gameCanvas').addEventListener('pointerdown',canvasDown);$('#gameCanvas').addEventListener('pointermove',canvasMove);$('#gameCanvas').addEventListener('pointerup',canvasUp);$('#gameCanvas').addEventListener('pointercancel',canvasUp);$('#canvasWrap').addEventListener('dragover',e=>e.preventDefault());$('#canvasWrap').addEventListener('drop',e=>{e.preventDefault();let type=e.dataTransfer.getData('text/object');if(type){let r=$('#gameCanvas').getBoundingClientRect();addObject(type,(e.clientX-r.left)*project.width/r.width,(e.clientY-r.top)*project.height/r.height)}});$('#clearConsole').onclick=()=>$('#console').innerHTML='';$$('[data-tab]').forEach(b=>b.onclick=()=>{$$('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));$('#console').classList.toggle('hidden',b.dataset.tab!=='console');$('#helpPanel').classList.toggle('hidden',b.dataset.tab!=='help');$('#clearConsole').classList.toggle('hidden',b.dataset.tab!=='console')});document.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select'))return;if(running){keys[e.key===' '?'Space':e.key]=true;if(e.key==='Escape')stopGame();if(e.key===' ')e.preventDefault();return}if(e.ctrlKey&&e.key.toLowerCase()==='s'){e.preventDefault();saveCurrent();return}if(e.ctrlKey&&e.key.toLowerCase()==='z'){e.preventDefault();undo();return}if(e.ctrlKey&&e.key.toLowerCase()==='y'){e.preventDefault();redo();return}if(e.ctrlKey&&e.key.toLowerCase()==='d'){e.preventDefault();duplicateSelected();return}if(e.key==='Delete'||e.key==='Backspace'){deleteSelected();return}if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)&&selected){const o=project.objects.find(x=>x.id===selected);if(o){e.preventDefault();snapshot();const step=e.shiftKey?10:1;o.x+=e.key==='ArrowLeft'?-step:e.key==='ArrowRight'?step:0;o.y+=e.key==='ArrowUp'?-step:e.key==='ArrowDown'?step:0;draw();renderInspector();persist();renderHierarchy()}return}if(e.key==='v'||e.key==='V')setTool('select');if(e.key==='r'||e.key==='R')setTool('rect');if(e.key==='c'||e.key==='C')setTool('circle');if(e.key==='t'||e.key==='T')setTool('text');if(e.key===' '){e.preventDefault();startGame()}});document.addEventListener('keyup',e=>{keys[e.key===' '?'Space':e.key]=false});window.addEventListener('beforeunload',()=>{if(project)persist()})}
window.IlyasStudioBridge={
 getProject:()=>project,
 getSelected:()=>project?.objects.find(x=>x.id===selected)||null,
 getRunning:()=>running,
 startPlay:()=>startGame(),
 stopPlay:()=>stopGame(),
 restartPlay:()=>restartGame(),
 pausePlay:()=>{if(running&&game)game.paused=true},
 resumePlay:()=>{if(running&&game)game.paused=false},
 getScene:()=>project?.objects||[],
 getGameState:()=>({project:project?{id:project.id,name:project.name,width:project.width,height:project.height,bg:project.bg}:null,objects:(running&&game?game.objects:project?.objects||[]).filter(o=>o.alive!==false),running,score:game?.score||0,paused:game?.paused||false,won:game?.won||false,lost:game?.lost||false}),
 saveProject:()=>{if(project){persist();renderDashboard()}},
 selectObject:id=>{selected=id;renderHierarchy();renderInspector();draw()},
 addObject:(type,x,y)=>{addObject(type,x,y)},
 log:(message,level='info')=>log(String(message),level==='error'?'error':level==='warning'?'info':'ok'),
 input:action=>{let map={left:['ArrowLeft','a'],right:['ArrowRight','d'],up:['ArrowUp','w'],down:['ArrowDown','s'],jump:['Space','ArrowUp','w'],jump_pressed:['Space','ArrowUp','w'],dash_pressed:['e','E']};return (map[action]||[action]).some(k=>!!keys[k])},
 isOnFloor:node=>{if(!node)return false;let live=running&&game?game.objects:project?.objects||[];return !!node.onGround||node.y+node.h/2>=(project?.height||540)-1||live.some(o=>o!==node&&o.alive!==false&&o.collision&&['Ground','Platform','Moving platform'].includes(o.type)&&Math.abs(node.x-o.x)<(node.w+o.w)/2&&Math.abs(node.y+node.h/2-(o.y-o.h/2))<5)}
};
loadStore();bind();renderDashboard();setView('dash');
})();